import numpy as np
from math import factorial, e
# Inclusion-exclusion: the chance that a random permutation of n items has no fixed point
def p_derangement(n):
    return sum((-1) ** k / factorial(k) for k in range(n + 1))
rng = np.random.default_rng(1)
for n in (3, 5, 10, 20):
    sim = np.mean([np.all(rng.permutation(n) != np.arange(n)) for _ in range(20000)])
    print(f"n = {n:2d}: inclusion-exclusion {p_derangement(n):.5f}, simulation {sim:.4f}")
print(f"limit 1/e = {1 / e:.5f}")
